const projectDialog=document.getElementById('project-dialog');
projectDialog.querySelector('.close').addEventListener('click',()=>projectDialog.close());
projectDialog.addEventListener('click',e=>{if(e.target===projectDialog){const r=projectDialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)projectDialog.close()}});
const projects={"forensics": {"title": "Following the digital trail.", "type": "DIGITAL FORENSICS / TRYHACKME LEARNING LAB", "body": "Examining the HASAN2.E01 Windows disk image in Autopsy, following clues across user accounts, scripts, and recent-file artefacts.", "contribution": "I searched the disk image for relevant files, inspected Windows user-account records, and examined a PowerShell script and suspicious shortcuts. I used file paths and text previews to record where each clue came from.", "findings": ["Located exploit.ps1 on the shreya user’s Desktop. Its visible code checks administrator-group membership and includes commands to create a hacked.txt file under another user’s Desktop. This describes the script’s content, not proof that it executed.", "Reviewed the SAM-derived user-account results, which show 15 records in Autopsy, including named users and built-in accounts.", "Found kiwi_passwords.yar.lnk with a target path under a mimikatz_trunk directory in the H4S4N profile. The shortcut gives a lead to investigate; its presence alone does not establish credential theft."], "lesson": "Start with a question, preserve the path to the artefact, and distinguish a file’s contents from evidence of execution. Correlating accounts, scripts, and shortcuts gives a stronger explanation than treating one suspicious filename as a conclusion.", "note": "Screenshots are from my training investigation. Account names and paths belong to the supplied lab image.", "images": [["autopsy-powershell", "PowerShell script selected in Autopsy, with its path and text preview."], ["autopsy-users", "SAM-derived Windows user-account records."], ["autopsy-shortcut", "Keyword search result showing a shortcut and its target path."]]}, "mongodb": {"title": "The right access. Nothing extra.", "type": "DATABASE SECURITY / COURSEWORK LAB", "body": "A Docker-based MongoDB exercise exploring authentication and the scope of database permissions.", "contribution": "I connected to the secure-mongo container with mongosh as dataScientist01, using customer_data as the authentication database, and attempted an insert from the test database to check access enforcement.", "findings": ["The shell authenticated and connected successfully; the screenshot records MongoDB 8.2.7 and mongosh 2.8.2.", "The attempted db.test.insertOne operation returned MongoServerError[Unauthorized]: not authorized on test to execute command.", "This captures a denied write to test. It does not establish that every write is denied or demonstrate the account’s complete role configuration."], "lesson": "Successful login does not grant access to every database. Check the active database and test both permitted and prohibited operations when validating least privilege.", "note": "Evidence extracted from my Module 6 lab report. The captured result verifies this specific denied operation; a successful permitted-operation test would extend the evidence.", "images": [["mongodb-denied", "Authenticated MongoDB session followed by an unauthorized insert into test."]]}, "arena": {"title": "Putting software fixes to the test.", "type": "SOFTWARE VERIFICATION / HACKATHON PROJECT", "body": "AgentArena explores how coding agents investigate software bugs and how proposed fixes can be assessed using tests in isolated Docker environments.", "contribution": "My project focuses on making software fixes inspectable: the bug, proposed patch, and verification evidence should be understandable together.", "contributionLabel": "Project focus", "findings": ["The submitted screenshot shows the workbench interface, run-history navigation, and an API-connected indicator.", "Its built-in shipping example illustrates how a test suite can miss the exact 1 kg boundary. The interface explicitly labels this as an example rather than a live result."], "lesson": "A passing test suite supports a claim; it does not prove the absence of defects. Boundary cases and clear separation between demonstration data and recorded results make verification more useful.", "note": "The screenshot documents the interface. It does not establish a completed live run or a measured benchmark result. The demo may depend on backend availability.", "images": [["agentarena", "AgentArena workbench and its labelled built-in shipping example."]], "url": "https://agentarena-xi.vercel.app", "label": "Visit AgentArena"}, "hadoop": {"title": "Getting the cluster to wake up.", "type": "LINUX & DATA INFRASTRUCTURE / COURSEWORK LAB", "body": "Setting up a single-node Hadoop 3.3.6 environment on Kali Linux, with HDFS and YARN.", "contribution": "I installed dependencies, configured localhost SSH, set environment variables, edited Hadoop configuration files, formatted the NameNode, and started HDFS and YARN. I checked the running Java services and opened the web interfaces.", "findings": ["The jps screenshot lists NameNode, DataNode, SecondaryNameNode, ResourceManager, and NodeManager processes.", "The report includes the NameNode and ResourceManager web interfaces and HDFS command output.", "Setup required troubleshooting missing APT repositories, an incorrect source-package download, Java availability, JAVA_HOME, and services that initially failed to start."], "lesson": "Verify each dependency and configuration step before moving on. Process lists, service output, and web interfaces are useful checks together. Recording the eventual working configuration matters as much as recording the errors.", "note": "This is a local infrastructure learning lab, not a production-secured Hadoop deployment. My report describes Java 11, while a formatting screenshot shows Java 8 paths; I would recheck the final runtime before presenting it as a reproducible setup.", "images": [["hadoop-services", "jps output showing the Hadoop and YARN processes."], ["hadoop-namenode", "Hadoop NameNode web interface from the lab report."]]}};
document.querySelectorAll('[data-project]').forEach(b=>b.onclick=()=>{
 const p=projects[b.dataset.project];
 document.getElementById('project-content').innerHTML=`<div class="case-meta">${p.type}</div><h2>${p.title}</h2><p>${p.body}</p><h3>${p.contributionLabel||'My contribution'}</h3><p>${p.contribution}</p><h3>What I found</h3><ul class="notebook-list">${p.findings.map(x=>`<li>${x}</li>`).join('')}</ul><h3>What I learned</h3><p>${p.lesson}</p><h3>From the lab notebook</h3><p class="evidence-hint">Select a screenshot to inspect it at full size.</p><div class="project-evidence">${p.images.map(([file,caption])=>`<figure><a href="assets/projects/${file}.jpg" target="_blank" rel="noopener noreferrer" aria-label="Open screenshot: ${caption}"><img src="assets/projects/${file}.jpg" alt="${caption}" loading="lazy"></a><figcaption>${caption}</figcaption></figure>`).join('')}</div><p class="note">${p.note}</p>${p.url?`<a class="project-link" href="${p.url}" target="_blank" rel="noopener noreferrer">${p.label} ↗</a>`:''}`;
 projectDialog.showModal();projectDialog.scrollTop=0;
});

const deskNotes=[
 {symbol:'⌕',title:'There’s usually<br>more to the story.',body:'I’m drawn to the part where scattered details start making sense. That’s what keeps me exploring security analysis and digital forensics.',note:'Start with a good question.'},
 {symbol:'{ }',title:'A small toolkit.<br>A lot of curiosity.',body:'Wireshark, Nmap, Autopsy, Burp Suite, and more. My toolkit is growing through cybersecurity learning, coursework, and projects.',note:'Learn it. Try it. Write it down.'},
 {symbol:'↗',title:'The next chapter?<br>Learning with a team.',body:'I’m working toward security analyst opportunities, while exploring the wider field. I’d love to bring my curiosity to an internship or entry-level role.',note:'There’s still so much to learn.'}
];
document.querySelectorAll('[data-desk]').forEach(button=>button.addEventListener('click',()=>{const i=Number(button.dataset.desk);const item=deskNotes[i];document.querySelectorAll('[data-desk]').forEach(b=>b.setAttribute('aria-pressed',b===button));document.getElementById('desk-page').textContent=String(i+1).padStart(2,'0');document.getElementById('desk-content').innerHTML=`<span class="desk-symbol" aria-hidden="true">${item.symbol}</span><h2>${item.title}</h2><p>${item.body}</p><span class="hand-note">${item.note}</span>`}));
